#include <zephyr/kernel.h>
#include <zephyr/ztest.h>

#define TEST_TICKS_TO_SLEEP 50

/*
 * @brief Test k_sleep() behavior at different initialization levels.
 *
 * This test verifies that k_sleep() behaves as expected depending on
 * whether the kernel is fully initialized or not.
 *
 * - PRE_KERNEL_1: k_sleep() should return the full requested duration
 *                 as the system clock is not yet running.
 * - PRE_KERNEL_2: k_sleep() might return the full requested duration
 *                 or a partial duration, depending on clock setup.
 *                 For this test, we expect it to return the full duration.
 * - POST_KERNEL: k_sleep() should complete fully and return 0.
 */

static k_timeout_t sleep_duration = K_TICKS(TEST_TICKS_TO_SLEEP);

/*
 * Helper function to call k_sleep and print results.
 * This function is called from different init levels.
 */
static void do_sleep_test(const char *level_str, k_timeout_t duration,
                          uint32_t *actual_ticks_ptr)
{
    k_timeout_t remaining_time;

    printk("Calling k_sleep() at %s level for %d ticks\n",
           level_str, duration.ticks);

    remaining_time = k_sleep(duration);
    *actual_ticks_ptr = remaining_time.ticks;

    printk("k_sleep() ticks at %s level: %u\n", level_str, *actual_ticks_ptr);
}

/* Variables to store actual sleep ticks at different levels */
static uint32_t actual_pre_kernel_1_sleep_ticks;
static uint32_t actual_pre_kernel_2_sleep_ticks;
static uint32_t actual_post_kernel_sleep_ticks;

/*
 * Test entry point for PRE_KERNEL_1.
 * This function is called very early in the boot process.
 */
static int pre_kernel_1_sleep_entry(void)
{
    do_sleep_test("PRE_KERNEL_1", sleep_duration, &actual_pre_kernel_1_sleep_ticks);
    return 0;
}

SYS_INIT(pre_kernel_1_sleep_entry, PRE_KERNEL_1, 0);

/*
 * Test entry point for PRE_KERNEL_2.
 * This function is called after PRE_KERNEL_1.
 */
static int pre_kernel_2_sleep_entry(void)
{
    do_sleep_test("PRE_KERNEL_2", sleep_duration, &actual_pre_kernel_2_sleep_ticks);
    return 0;
}

SYS_INIT(pre_kernel_2_sleep_entry, PRE_KERNEL_2, 0);

/*
 * Test entry point for POST_KERNEL.
 * This function is called after the kernel is fully initialized.
 */
static int post_kernel_sleep_entry(void)
{
    do_sleep_test("POST_KERNEL", sleep_duration, &actual_post_kernel_sleep_ticks);
    return 0;
}

SYS_INIT(post_kernel_sleep_entry, POST_KERNEL, 0);


ZTEST_SUITE(earlysleep, NULL, NULL, NULL, NULL, NULL);

/*
 * Main test function that runs assertions after all init levels have executed.
 */
ZTEST(earlysleep, test_early_sleep)
{
    printk("Testing early sleeping\n");
    printk("msec per tick: %d.000, ticks to sleep: %d\n",
           (int)k_ms_per_tick_get(), TEST_TICKS_TO_SLEEP);

    /*
     * PRE_KERNEL_1: k_sleep() should not sleep, returning the full duration.
     * This is because the system clock is not yet initialized.
     */
    zassert_equal(actual_pre_kernel_1_sleep_ticks, TEST_TICKS_TO_SLEEP,
                  "k_sleep() at PRE_KERNEL_1 did not return full duration. Remaining ticks: %u",
                  actual_pre_kernel_1_sleep_ticks);

    /*
     * PRE_KERNEL_2: k_sleep() should not sleep, returning the full duration.
     * Similar to PRE_KERNEL_1, clock might not be fully ready for actual sleep.
     */
    zassert_equal(actual_pre_kernel_2_sleep_ticks, TEST_TICKS_TO_SLEEP,
                  "k_sleep() at PRE_KERNEL_2 did not return full duration. Remaining ticks: %u",
                  actual_pre_kernel_2_sleep_ticks);

    /*
     * POST_KERNEL: k_sleep() should complete fully and return 0.
     * At this stage, the system clock is fully operational.
     */
    zassert_equal(actual_post_kernel_sleep_ticks, 0,
                  "k_sleep() at POST_KERNEL did not complete fully. Remaining ticks: %u",
                  actual_post_kernel_sleep_ticks);
}
